<script setup>
import {ref,computed,watch,nextTick,provide} from 'vue'
import {parseDocumentText,documentOperations,operationAt,patchDocumentText,updateOperation,effectiveParameters,updateParameters,inheritedParameter,resolveLocal,formatJSON,formatValue,editOperationJSON,mergeDocumentTexts,documentTextFromResponse} from './documentEditModel.js'
import {confirmAction} from '../shared/shadcnFeedback.js'
import {toast} from '../shared/composables/toast.js'
import OptionPicker from '../shared/components/OptionPicker.vue'
import SchemaEditor from './SchemaEditor.vue'
import RequirementPicker from './RequirementPicker.vue'
import {Accordion,AccordionItem,AccordionTrigger,AccordionContent,Button,Checkbox,Field,FieldLabel,Input,Textarea,Tabs,TabsList,TabsTrigger,SheetFooter,Spinner,Badge} from '../shared/shadcn-ui.js'
const props=defineProps({text:String,source:Object,operation:String,workItem:[String,Number]}),emit=defineEmits(['cancel','saved','state'])
const text=ref(props.text),operation=ref(props.operation),mode=ref('basic'),busy=ref(false),preview=ref(null),showPreview=ref(false),requirementID=ref(props.workItem||''),fieldRequirements=ref({}),additions=ref([]),region=ref(null),rawMode=ref('operation'),jsonDraft=ref(''),jsonDirty=ref(false),uncertain=ref(false)
const stale=ref(false),pendingExamples=ref(new Set())
provide('apiDocumentPending',(key,pending)=>{const next=new Set(pendingExamples.value);if(pending)next.add(key);else next.delete(key);pendingExamples.value=next})
const activeSource=ref({...props.source}),baseText=ref(props.text),conflict=ref(null),conflictChoices=ref({}),conflictDraft=ref('')
const merged=computed(()=>conflict.value?mergeDocumentTexts(baseText.value,conflictDraft.value,conflict.value.document_text,conflictChoices.value):null)
const dirty=computed(()=>pendingExamples.value.size>0||text.value!==props.text||jsonDirty.value||!!requirementID.value||Object.values(fieldRequirements.value).some(Boolean))
const parsed=computed(()=>{try{return parseDocumentText(text.value,false)}catch{return null}}),op=computed(()=>parsed.value?operationAt(parsed.value,operation.value):null),choices=computed(()=>parsed.value?documentOperations(parsed.value):[])
const params=computed(()=>{try{return effectiveParameters(parsed.value,operation.value)}catch{return []}})
const body=computed(()=>{try{return resolveLocal(op.value?.requestBody,parsed.value)}catch{return {}}})
const responses=computed(()=>Object.entries(op.value?.responses||{}).map(([status,value])=>{try{return {status,...resolveLocal(value,parsed.value)}}catch{return {status,description:'请在高级 JSON 中编辑外部引用'}}}))
const uniqueAdditions=computed(()=>[...new Map(additions.value.map(f=>[f.pointer,f])).values()])
watch([dirty,busy],()=>emit('state',{dirty:dirty.value,busy:busy.value}),{immediate:true})
watch([text,requirementID,fieldRequirements],()=>{preview.value=null},{deep:true})
watch([operation,rawMode],()=>{if(!jsonDirty.value)resetJSON()})
function resetJSON(){jsonDraft.value=rawMode.value==='document'?text.value:formatValue(op.value);jsonDirty.value=false}
watch(mode,(v,old)=>{if(v==='json'&&!jsonDirty.value)resetJSON();if(old==='json'&&jsonDirty.value)applyJSON()})
function issue(e){toast(e.message||String(e),'error');nextTick(()=>region.value?.querySelector('[aria-invalid=true],textarea[aria-label="OpenAPI JSON 编辑"],input')?.focus())}
function selectMode(value){if(pendingExamples.value.size){issue(Error('请先修正未完成的 JSON 示例'));return}if(mode.value==='json'&&!applyJSON())return;mode.value=value}
function patch(field,value){try{text.value=patchDocumentText(text.value,operation.value,field,value)}catch(e){issue(e)}}
function update(fn){try{text.value=updateOperation(text.value,operation.value,fn)}catch(e){issue(e)}}
function editParams(next){try{text.value=updateParameters(text.value,operation.value,next)}catch(e){issue(e)}}
function param(i,key,value){const list=params.value.map(p=>({...p}));list[i][key]=value;if(key==='in'&&value==='path')list[i].required=true;editParams(list)}
function addParam(){let name='param',i=1;while(params.value.some(p=>p.name===name))name='param'+i++;editParams([...params.value,{in:'query',name,schema:{type:'string'}}])}
function requestSchema(media,schema){update((o,d)=>{const b=resolveLocal(o.requestBody,d);b.content={...b.content,[media]:{...b.content?.[media],schema}};o.requestBody=b})}
function response(status,key,value){update((o,d)=>{o.responses={...o.responses,[status]:{...resolveLocal(o.responses?.[status],d),[key]:value}}})}
function addResponse(){const status=['200','201','400','401','404','500','default'].find(s=>!op.value.responses?.[s]);if(!status)return toast('更多状态码请在高级 JSON 添加','info');response(status,'description','响应说明')}
function applyJSON(){if(pendingExamples.value.size){issue(Error('请先修正未完成的 JSON 示例'));return false}if(!jsonDirty.value)return true;try{const next=rawMode.value==='document'?formatJSON(jsonDraft.value):editOperationJSON(text.value,operation.value,jsonDraft.value);parseDocumentText(next);text.value=next;jsonDirty.value=false;return true}catch(e){mode.value='json';issue(e);return false}}
async function canClose(){return !busy.value&&(!dirty.value||await confirmAction('文档编辑尚未保存，确认放弃改动？','退出文档编辑'))}
async function close(){if(await canClose())emit('cancel')}
async function request(action,body,extra={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),60000);try{const q=new URLSearchParams({service:activeSource.value.service,environment:activeSource.value.environment,...extra});const r=await fetch('api/api-documents/'+activeSource.value.id+'/'+action+'?'+q,{method:'POST',headers:{'Content-Type':'application/json'},body,signal:controller.signal});const data=await r.json();if(!r.ok){const e=Error(data.error||'文档保存失败');e.status=r.status;throw e}return data}finally{clearTimeout(timer)}}
function submission(context){return '{"document":'+text.value+',"change_context":'+JSON.stringify(context)+'}'}
async function readLatest(){const q=new URLSearchParams({service:activeSource.value.service,environment:activeSource.value.environment});const r=await fetch('api/api-documents?'+q);const v=await r.json();if(!r.ok)throw Error(v.error||'核对失败');const items=Array.isArray(v)?v:v.items||[],latest=items[0];if(!latest)throw Error('没有可核对的修订');const detail=await fetch('api/api-documents/'+latest.id+'?'+q),raw=await detail.text();if(!detail.ok)throw Error('读取最新修订失败');const data=JSON.parse(raw);return {...data,document_text:documentTextFromResponse(raw)}}
async function inspectLatest(){if(busy.value||!applyJSON())return;busy.value=true;try{conflict.value=await readLatest();conflictDraft.value=text.value;conflictChoices.value={};toast('已读取最新修订，请核对合并结果','info')}catch(e){issue(e)}finally{busy.value=false}}
function acceptMerge(){if(!merged.value||merged.value.conflicts.length)return;try{parseDocumentText(merged.value.text);text.value=merged.value.text;baseText.value=conflict.value.document_text;activeSource.value={...activeSource.value,id:conflict.value.id};conflict.value=null;stale.value=false;preview.value=null;additions.value=[];resetJSON();toast('已合并到最新修订，尚未保存','success')}catch(e){issue(e)}}
function changeContext(){const ref=id=>{if(!/^[1-9]\d*$/.test(String(id))||!Number.isSafeInteger(Number(id)))throw Error('请选择有效的工作项');return {id:Number(id)}};const fields={};for(const [pointer,id] of Object.entries(fieldRequirements.value))if(id)fields[pointer]=ref(id);return {work_item:requirementID.value?ref(requirementID.value):undefined,fields}}
async function check(){if(busy.value||!applyJSON())return;busy.value=true;try{parseDocumentText(text.value);preview.value=await request('edit-preview',submission(changeContext()));additions.value=preview.value.field_additions||[];showPreview.value=true}catch(e){issue(e)}finally{busy.value=false}}
async function save(){if(busy.value||uncertain.value||!applyJSON())return;busy.value=true;let writing=false;try{
 parseDocumentText(text.value);const p=await request('edit-preview',submission(changeContext()));preview.value=p
 if(p.unchanged){toast('文档内容未变化，未创建修订','info');return}
 writing=true;const result=await request('edit',submission(p.change_context),{expected_baseline_id:String(p.source_id),expected_digest:p.digest,...(p.maintainer_digest?{expected_maintainer_digest:p.maintainer_digest}:{})})
 emit('saved',result);toast('已保存，历史修订自动保留','success')
 }catch(e){if(e.status===409)stale.value=true;if(writing&&(!e.status||e.status>=500))uncertain.value=true;issue(Error(e.message+'；编辑内容已保留。'+(uncertain.value?'结果待核对，请勿重复保存。':e.status===409?'请点击“核对最新修订”后合并。':'')))}finally{busy.value=false}}
async function reconcile(){if(busy.value)return;busy.value=true;try{const q=new URLSearchParams({service:props.source.service,environment:props.source.environment});const r=await fetch('api/api-documents?'+q);const v=await r.json();if(!r.ok)throw Error(v.error||'核对失败');const items=Array.isArray(v)?v:v.items||[],latest=items[0];if(latest?.digest===preview.value?.digest&&latest.id>preview.value.source_id&&latest.baseline_id===preview.value.source_id){emit('saved',{id:latest.id});toast('已找到内容一致的新修订','success')}else toast('未确认保存成功；请保留草稿并核对最新修订，未重放保存','warning')}catch(e){issue(e)}finally{busy.value=false}}
defineExpose({canClose})
</script>
<template>
 <div ref="region" class="flex min-h-0 flex-1 flex-col overflow-hidden">
  <div class="min-h-0 flex-1 space-y-5 overflow-y-auto p-5">
   <div class="flex flex-wrap items-center gap-2 text-sm"><Badge variant="outline">{{activeSource.service}} · {{activeSource.environment}} · 修订 #{{activeSource.id}}</Badge></div>
   <Field><FieldLabel>编辑接口</FieldLabel><OptionPicker :model-value="operation" :disabled="busy||jsonDirty||!!conflict||pendingExamples.size>0" :options="choices" aria-label="选择编辑接口" @update:model-value="operation=$event"/></Field>
   <Tabs :model-value="mode" @update:model-value="selectMode"><TabsList class="h-auto max-w-full flex-wrap"><TabsTrigger value="basic">基本信息</TabsTrigger><TabsTrigger value="parameters">参数</TabsTrigger><TabsTrigger value="request">请求体</TabsTrigger><TabsTrigger value="responses">响应</TabsTrigger><TabsTrigger value="json">高级 JSON</TabsTrigger></TabsList></Tabs>
   <fieldset :disabled="busy||!!conflict" class="min-w-0 space-y-5">
    <template v-if="mode==='basic'&&op"><Field><FieldLabel>接口名称</FieldLabel><Input :model-value="op.summary||''" aria-label="接口名称" @update:model-value="patch('summary',$event)"/></Field><Field><FieldLabel>接口说明</FieldLabel><Textarea :model-value="op.description||''" rows="4" aria-label="接口说明" @update:model-value="patch('description',$event)"/></Field><div class="grid gap-4 sm:grid-cols-2"><Field><FieldLabel>接口维护人</FieldLabel><Input :model-value="op['x-maintainer']||''" placeholder="未显式指定时沿用原归属" @update:model-value="patch('x-maintainer',$event)"/></Field><Field><FieldLabel>功能分组</FieldLabel><Input :model-value="(op.tags||[]).join(', ')" placeholder="多个分组以逗号分隔" @update:model-value="patch('tags',$event)"/></Field></div><Accordion type="single" collapsible><AccordionItem value="info"><AccordionTrigger>文档信息</AccordionTrigger><AccordionContent class="grid gap-4 sm:grid-cols-2"><Field><FieldLabel>文档标题</FieldLabel><Input :model-value="parsed.info.title" @update:model-value="patch('info.title',$event)"/></Field><Field><FieldLabel>业务版本（修订自动记录）</FieldLabel><Input :model-value="parsed.info.version" @update:model-value="patch('info.version',$event)"/></Field></AccordionContent></AccordionItem></Accordion></template>
    <template v-if="mode==='parameters'"><section v-for="(p,i) in params" :key="i" class="min-w-0 space-y-3 rounded-lg border p-3"><p v-if="inheritedParameter(parsed,operation,p)" class="text-xs text-muted-foreground">路径级公共参数：说明与类型可单独覆盖，名称和位置请在完整 JSON 中统一调整。</p><div class="flex flex-wrap items-end gap-2"><Field class="min-w-0 flex-1"><FieldLabel>参数名</FieldLabel><Input :model-value="p.name" :disabled="inheritedParameter(parsed,operation,p)" :aria-label="'参数名 '+i" @update:model-value="param(i,'name',$event)"/></Field><OptionPicker :model-value="p.in" :disabled="inheritedParameter(parsed,operation,p)" :options="['query','path','header','cookie'].map(value=>({value,label:value}))" aria-label="参数位置" @update:model-value="param(i,'in',$event)"/><Button variant="ghost" :disabled="inheritedParameter(parsed,operation,p)" @click="editParams(params.filter((_,n)=>n!==i))">移除</Button></div><label class="flex items-center gap-2 text-sm"><Checkbox :model-value="!!p.required||p.in==='path'" :disabled="p.in==='path'" @update:model-value="param(i,'required',$event)"/>必填</label><Field><FieldLabel>参数说明</FieldLabel><Input :model-value="p.description||''" @update:model-value="param(i,'description',$event)"/></Field><SchemaEditor :model-value="p.schema||{}" :document="parsed" :label="p.name||'参数'" @update:model-value="param(i,'schema',$event)"/></section><p v-if="!params.length" class="py-5 text-center text-sm text-muted-foreground">暂无参数。</p><Button variant="outline" @click="addParam">＋ 添加参数</Button></template>
    <template v-if="mode==='request'"><section v-for="(value,media) in body.content||{}" :key="media" class="min-w-0 space-y-3 rounded-lg border p-3"><Badge variant="outline">{{media}}</Badge><SchemaEditor :model-value="value.schema||{}" :document="parsed" label="请求体" @update:model-value="requestSchema(media,$event)"/></section><p v-if="!Object.keys(body.content||{}).length" class="py-5 text-center text-sm text-muted-foreground">暂无请求体。</p><Button v-if="!body.content?.['application/json']" variant="outline" @click="requestSchema('application/json',{type:'object',properties:{}})">＋ 添加 JSON 请求体</Button></template>
    <template v-if="mode==='responses'"><section v-for="r in responses" :key="r.status" class="min-w-0 space-y-3 rounded-lg border p-3"><div class="flex items-center gap-3"><Badge variant="outline">{{r.status}}</Badge><Input :model-value="r.description||''" :aria-label="r.status+'响应说明'" @update:model-value="response(r.status,'description',$event)"/><Button variant="ghost" :disabled="responses.length===1" @click="update(o=>delete o.responses[r.status])">移除</Button></div><div v-for="(v,media) in r.content||{}" :key="media" class="space-y-3"><p class="text-sm">{{media}}</p><SchemaEditor :model-value="v.schema||{}" :document="parsed" :label="r.status+'响应'" @update:model-value="response(r.status,'content',{...r.content,[media]:{...v,schema:$event}})"/></div><Button v-if="!r.content?.['application/json']" variant="outline" size="sm" @click="response(r.status,'content',{...r.content,'application/json':{schema:{type:'object',properties:{}}}})">＋ JSON 响应字段</Button></section><Button variant="outline" @click="addResponse">＋ 添加响应</Button></template>
    <template v-if="mode==='json'"><div class="flex flex-wrap gap-2"><OptionPicker :model-value="rawMode" :disabled="jsonDirty" :options="[{value:'operation',label:'当前接口 JSON'},{value:'document',label:'完整 OpenAPI JSON'}]" aria-label="JSON 编辑范围" @update:model-value="rawMode=$event"/><Button variant="outline" @click="()=>{try{jsonDraft=formatJSON(jsonDraft)}catch(e){issue(e)}}">格式化</Button><Button variant="outline" :disabled="!jsonDirty" @click="applyJSON">应用 JSON</Button></div><Textarea :model-value="jsonDraft" @update:model-value="jsonDraft=$event;jsonDirty=true" class="min-h-96 font-mono text-xs" aria-label="OpenAPI JSON 编辑" spellcheck="false"/></template>
   </fieldset>
   <section v-if="conflict" class="min-w-0 space-y-3 rounded-lg border p-3" aria-label="文档冲突核对"><p class="text-sm">原基线 #{{activeSource.id}} → 最新修订 #{{conflict.id}}。不同字段自动合并，同一位置需明确选择。</p><div v-for="c in merged.conflicts" :key="c.path" class="min-w-0 space-y-2"><code class="block break-all text-xs">{{c.path}}</code><div class="grid min-w-0 gap-2 sm:grid-cols-2"><pre class="max-h-32 overflow-auto rounded bg-muted p-2 text-xs">我的：{{c.mine}}</pre><pre class="max-h-32 overflow-auto rounded bg-muted p-2 text-xs">最新：{{c.latest}}</pre></div><OptionPicker v-model="conflictChoices[c.path]" :options="[{value:'mine',label:'采用我的值'},{value:'latest',label:'采用最新值'}]" placeholder="请选择冲突处理方式"/></div><Button variant="outline" :disabled="merged.conflicts.length>0||busy" @click="acceptMerge">合并到最新修订继续编辑</Button></section><Field><FieldLabel>本次变更关联需求 / Bug（选填）</FieldLabel><RequirementPicker v-model="requirementID" :disabled="busy"/></Field>
   <Accordion v-if="uniqueAdditions.length" type="single" collapsible><AccordionItem value="fields"><AccordionTrigger>新增字段单独关联需求（{{uniqueAdditions.length}}）</AccordionTrigger><AccordionContent class="space-y-3"><div v-for="f in uniqueAdditions" :key="f.pointer" class="space-y-2 rounded-md border p-3"><p class="break-all text-sm">{{f.in}} · {{f.name}}</p><RequirementPicker v-model="fieldRequirements[f.pointer]" :disabled="busy"/></div></AccordionContent></AccordionItem></Accordion>
   <section v-if="preview&&showPreview" aria-label="文档编辑预览" class="space-y-3 rounded-lg border p-4"><p>接口：新增 {{preview.summary.added}} · 修改 {{preview.summary.modified}} · 删除 {{preview.summary.removed}}</p><p v-if="preview.field_additions_error" class="text-sm text-destructive">字段分析未完成：{{preview.field_additions_error}}</p><p v-if="preview.unchanged" class="text-sm text-muted-foreground">文档内容没有变化。</p><div v-for="change in preview.changes" :key="change.id" class="space-y-1 text-sm"><p class="font-medium">{{({added:'新增',removed:'删除',modified:'修改'})[change.kind]}} · {{change.method}} {{change.path}}</p><p v-for="f in change.fields" :key="f.path" class="break-all font-mono text-xs">{{f.path}}：{{f.before_present?f.before:'（不存在）'}} → {{f.after_present?f.after:'（不存在）'}}</p></div><p v-if="preview.truncated" class="text-sm text-muted-foreground">明细已截断，请核对完整 JSON。</p></section>
  </div>
  <SheetFooter class="flex-wrap"><Button variant="outline" :disabled="busy" @click="close">返回文档</Button><Button variant="outline" :disabled="busy||!dirty" @click="check"><Spinner v-if="busy"/>查看变化</Button><Button v-if="stale" variant="outline" :disabled="busy||uncertain" @click="inspectLatest">核对最新修订</Button><Button v-if="uncertain" :disabled="busy" @click="reconcile">核对保存结果</Button><Button v-else :disabled="busy||!dirty||!!conflict" @click="save"><Spinner v-if="busy"/>保存</Button></SheetFooter>
 </div>
</template>
